"""Inventory operations used by checkout and order cancellation."""


def reserve_stock(inventory, product_id, quantity):
    if quantity <= 0 or inventory.get(product_id, 0) < quantity:
        raise ValueError("Insufficient stock or invalid quantity")
    inventory[product_id] -= quantity


def restore_stock(inventory, product_id, quantity):
    """Restore inventory when an order is cancelled."""
    inventory[product_id] = inventory.get(product_id, 0) + quantity

"""Small demonstration shop, deliberately containing an inventory cancellation bug."""
from .inventory import reserve_stock


def place_order(inventory, product_id, quantity):
    reserve_stock(inventory, product_id, quantity)
    return {"product_id": product_id, "quantity": quantity, "status": "placed"}


def cancel_order(order, inventory):
    """Cancel an order. Reserved inventory should become available again."""
    if order["status"] == "cancelled":
        return order
    order["status"] = "cancelled"
    return order

"""Price calculation for the example shop."""


def calculate_total(unit_price, quantity, discount=0):
    if not 0 <= discount <= 1:
        raise ValueError("Discount must be between zero and one")
    return round(unit_price * quantity * (1 - discount), 2)
